import { useCallback, useState, memo } from 'react';

// Child component that receives callback
const TodoItem = memo(function TodoItem({ todo, onToggle, onDelete }) {
  console.log(`TodoItem ${todo.id} rendered`);

  return (
    <div className={`todo ${todo.completed ? 'completed' : ''}`}>
      <input
        type="checkbox"
        checked={todo.completed}
        onChange={() => onToggle(todo.id)}
      />
      <span>{todo.text}</span>
      <button onClick={() => onDelete(todo.id)}>Delete</button>
    </div>
  );
});

function TodoApp() {
  const [todos, setTodos] = useState([]);
  const [filter, setFilter] = useState('all');
  const [newTodo, setNewTodo] = useState('');

  // Without useCallback, these functions are recreated on every render
  // causing TodoItem to re-render even when memo is used
  const handleToggle = useCallback((id) => {
    setTodos(prev => 
      prev.map(todo => 
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  }, []); // No dependencies - function never changes

  const handleDelete = useCallback((id) => {
    setTodos(prev => prev.filter(todo => todo.id !== id));
  }, []);

  // When callback depends on state
  const handleAdd = useCallback(() => {
    if (newTodo.trim()) {
      setTodos(prev => [...prev, {
        id: Date.now(),
        text: newTodo,
        completed: false
      }]);
      setNewTodo('');
    }
  }, [newTodo]); // Re-create when newTodo changes

  // Filter logic (could also be memoized with useMemo)
  const filteredTodos = todos.filter(todo => {
    if (filter === 'active') return !todo.completed;
    if (filter === 'completed') return todo.completed;
    return true;
  });

  return (
    <div>
      <input
        value={newTodo}
        onChange={(e) => setNewTodo(e.target.value)}
        onKeyPress={(e) => e.key === 'Enter' && handleAdd()}
      />
      <button onClick={handleAdd}>Add</button>

      <div>
        <button onClick={() => setFilter('all')}>All</button>
        <button onClick={() => setFilter('active')}>Active</button>
        <button onClick={() => setFilter('completed')}>Completed</button>
      </div>

      {filteredTodos.map(todo => (
        <TodoItem
          key={todo.id}
          todo={todo}
          onToggle={handleToggle}
          onDelete={handleDelete}
        />
      ))}
    </div>
  );
}
```

## Advanced Hooks

### useLayoutEffect - Synchronous DOM Updates
```jsx
import { useLayoutEffect, useRef, useState } from 'react';

function Tooltip({ children, text }) {
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const tooltipRef = useRef();
  const triggerRef = useRef();

  // useLayoutEffect runs synchronously after DOM mutations
  // but before the browser paints (prevents flicker)
  useLayoutEffect(() => {
    if (tooltipRef.current && triggerRef.current) {
      const triggerRect = triggerRef.current.getBoundingClientRect();
      const tooltipRect = tooltipRef.current.getBoundingClientRect();

      // Calculate position to avoid viewport overflow
      let x = triggerRect.left + triggerRect.width / 2 - tooltipRect.width / 2;
      let y = triggerRect.top - tooltipRect.height - 10;

      if (x < 0) x = 10;
      if (x + tooltipRect.width > window.innerWidth) {
        x = window.innerWidth - tooltipRect.width - 10;
      }

      if (y < 0) {
        y = triggerRect.bottom + 10;
      }

      setPosition({ x, y });
    }
  });

  return (
    <>
      <span ref={triggerRef}>{children}</span>
      <div
        ref={tooltipRef}
        className="tooltip"
        style={{
          position: 'fixed',
          left: position.x,
          top: position.y,
          zIndex: 1000
        }}
      >
        {text}
      </div>
    </>
  );
}
```

### Custom Hooks - Reusable Logic
```jsx
// useLocalStorage hook
function useLocalStorage(key, initialValue) {
  const [storedValue, setStoredValue] = useState(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.error(`Error reading localStorage key "${key}":`, error);
      return initialValue;
    }
  });

  const setValue = useCallback((value) => {
    try {
      const valueToStore = value instanceof Function ? value(storedValue) : value;
      setStoredValue(valueToStore);
      window.localStorage.setItem(key, JSON.stringify(valueToStore));
    } catch (error) {
      console.error(`Error setting localStorage key "${key}":`, error);
    }
  }, [key, storedValue]);

  return [storedValue, setValue];
}

// useAsync hook for data fetching
function useAsync(asyncFunction, dependencies = []) {
  const [state, setState] = useState({
    data: null,
    loading: true,
    error: null
  });

  useEffect(() => {
    let isCancelled = false;

    setState(prev => ({ ...prev, loading: true, error: null }));

    asyncFunction()
      .then(data => {
        if (!isCancelled) {
          setState({ data, loading: false, error: null });
        }
      })
      .catch(error => {
        if (!isCancelled) {
          setState({ data: null, loading: false, error });
        }
      });

    return () => {
      isCancelled = true;
    };
  }, dependencies);

  return state;
}

// useDebounce hook
function useDebounce(value, delay) {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

// Usage examples
function SearchComponent() {
  const [query, setQuery] = useState('');
  const [favorites, setFavorites] = useLocalStorage('favorites', []);
  const debouncedQuery = useDebounce(query, 500);

  const { data: results, loading, error } = useAsync(
    () => searchAPI(debouncedQuery),
    [debouncedQuery]
  );

  return (
    <div>
      <input
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search..."
      />

      {loading && <div>Searching...</div>}
      {error && <div>Error: {error.message}</div>}

      {results?.map(item => (
        <SearchResult
          key={item.id}
          item={item}
          isFavorite={favorites.includes(item.id)}
          onToggleFavorite={(id) => 
            setFavorites(prev => 
              prev.includes(id) 
                ? prev.filter(fav => fav !== id)
                : [...prev, id]
            )
          }
        />
      ))}
    </div>
  );
}
```

