### useReducer - Complex State Logic
```jsx
import { useReducer } from 'react';

// State shape
const initialState = {
  items: [],
  loading: false,
  error: null,
  filter: 'all'
};

// Action types
const ACTIONS = {
  SET_LOADING: 'SET_LOADING',
  SET_ITEMS: 'SET_ITEMS',
  ADD_ITEM: 'ADD_ITEM',
  REMOVE_ITEM: 'REMOVE_ITEM',
  SET_FILTER: 'SET_FILTER',
  SET_ERROR: 'SET_ERROR'
};

// Reducer function (pure, predictable)
function todoReducer(state, action) {
  switch (action.type) {
    case ACTIONS.SET_LOADING:
      return { ...state, loading: action.payload, error: null };

    case ACTIONS.SET_ITEMS:
      return { ...state, items: action.payload, loading: false };

    case ACTIONS.ADD_ITEM:
      return {
        ...state,
        items: [...state.items, { id: Date.now(), ...action.payload }]
      };

    case ACTIONS.REMOVE_ITEM:
      return {
        ...state,
        items: state.items.filter(item => item.id !== action.payload)
      };

    case ACTIONS.SET_FILTER:
      return { ...state, filter: action.payload };

    case ACTIONS.SET_ERROR:
      return { ...state, error: action.payload, loading: false };

    default:
      return state;
  }
}

function TodoApp() {
  const [state, dispatch] = useReducer(todoReducer, initialState);

  const addTodo = (text) => {
    dispatch({
      type: ACTIONS.ADD_ITEM,
      payload: { text, completed: false }
    });
  };

  const setFilter = (filter) => {
    dispatch({ type: ACTIONS.SET_FILTER, payload: filter });
  };

  return (
    <div>
      <TodoForm onAdd={addTodo} />
      <FilterButtons filter={state.filter} onFilterChange={setFilter} />
      <TodoList items={state.items} />
      {state.error && <Error message={state.error} />}
    </div>
  );
}
```

### Context API - Global State
```jsx
import { createContext, useContext, useReducer } from 'react';

// 1. Create Context
const AppContext = createContext();

// 2. Provider Component
export function AppProvider({ children }) {
  const [state, dispatch] = useReducer(appReducer, initialState);

  const value = {
    ...state,
    dispatch,
    // Derived values
    completedItems: state.items.filter(item => item.completed),
    activeItems: state.items.filter(item => !item.completed)
  };

  return (
    <AppContext.Provider value={value}>
      {children}
    </AppContext.Provider>
  );
}

// 3. Custom Hook for Context
export function useAppContext() {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useAppContext must be used within AppProvider');
  }
  return context;
}

// 4. Usage in Components
function TodoList() {
  const { items, dispatch } = useAppContext();

  const toggleTodo = (id) => {
    dispatch({ type: 'TOGGLE_ITEM', payload: id });
  };

  return (
    <ul>
      {items.map(item => (
        <TodoItem key={item.id} item={item} onToggle={toggleTodo} />
      ))}
    </ul>
  );
}
